To fix that, zero-init map_info via memset before each
bpf_obj_get_info_by_fd call.

Also, since the area of this code is touched, in general strcmp is
considered harmful, so let's convert it to strncmp and provide the
size of the array name for current map_info.

While at it, do s/continue/break/ once we have found the xsks_map to
terminate the search.

Fixes: 5750902a6e9b ("libbpf: proper XSKMAP cleanup")
Signed-off-by: Maciej Fijalkowski <maciej.fijalkowski@intel.com>
Signed-off-by: Daniel Borkmann <daniel@iogearbox.net>
Acked-by: Björn Töpel <bjorn.topel@intel.com>
Link: https://lore.kernel.org/bpf/20210303185636.18070-4-maciej.fijalkowski@intel.com

Here is the root cause:
The bug was caused by not clearing the `map_info` structure before each call to `bpf_obj_get_info_by_fd`, which could lead to the presence of outdated or invalid data in the structure. This could result in incorrect behavior when checking for the existence of the `xsks_map`, as previous iterations' data might incorrectly influence the outcome. Additionally, using `strcmp` without size limits posed a risk of buffer overflows, and the use of `continue` instead of `break` led to unnecessary iterations even after the desired map was found.

Here is the patch:

 static int xsk_lookup_bpf_maps(struct xsk_socket *xsk)
 {
 	__u32 i, *map_ids, num_maps, prog_len = sizeof(struct bpf_prog_info);
 	__u32 map_len = sizeof(struct bpf_map_info);
 	struct bpf_prog_info prog_info = {};
 	struct xsk_ctx *ctx = xsk->ctx;
 	struct bpf_map_info map_info;
 	int fd, err;

 	err = bpf_obj_get_info_by_fd(ctx->prog_fd, &prog_info, &prog_len);
 	if (err)
 		return err;

 	num_maps = prog_info.nr_map_ids;

 	map_ids = calloc(prog_info.nr_map_ids, sizeof(*map_ids));
 	if (!map_ids)
 		return -ENOMEM;

 	memset(&prog_info, 0, prog_len);
 	prog_info.nr_map_ids = num_maps;
 	prog_info.map_ids = (__u64)(unsigned long)map_ids;

 	err = bpf_obj_get_info_by_fd(ctx->prog_fd, &prog_info, &prog_len);
 	if (err)
 		goto out_map_ids;

 	ctx->xsks_map_fd = -1;

 	for (i = 0; i < prog_info.nr_map_ids; i++) {
 		fd = bpf_map_get_fd_by_id(map_ids[i]);
 		if (fd < 0)
 			continue;

+		memset(&map_info, 0, map_len);
 		err = bpf_obj_get_info_by_fd(fd, &map_info, &map_len);
 		if (err) {
 			close(fd);
 			continue;
 		}

-		if (!strcmp(map_info.name, "xsks_map")) {
+		if (!strncmp(map_info.name, "xsks_map", sizeof(map_info.name))) {
 			ctx->xsks_map_fd = fd;
-			continue;
+			break;
 		}

 		close(fd);
 	}

 	err = 0;
 	if (ctx->xsks_map_fd == -1)
 		err = -ENOENT;

 out_map_ids:
 	free(map_ids);
 	return err;
 }



